#include <vector>
#include <algorithm>
#include <cmath>

class Solution {
public:
    int minOperations(std::vector<std::vector<int>>& grid, int x) {
        std::vector<int> vals;
        for (const auto& row : grid) {
            for (int val : row) vals.push_back(val);
        }
        int rem = (vals[0] % x + x) % x;
        for (int v : vals) {
            if ((v % x + x) % x != rem) return -1;
        }
        std::sort(vals.begin(), vals.end());
        int median = vals[vals.size() / 2];
        long long ops = 0;
        for (int v : vals) ops += std::abs(v - median) / x;
        return ops;
    }
};

import java.util.*;

class Solution {
    public int minOperations(int[][] grid, int x) {
        int m = grid.length, n = grid[0].length;
        int[] vals = new int[m * n];
        int idx = 0;
        for (int[] row : grid) {
            for (int v : row) vals[idx++] = v;
        }
        int rem = (vals[0] % x + x) % x;
        for (int v : vals) {
            if ((v % x + x) % x != rem) return -1;
        }
        Arrays.sort(vals);
        int median = vals[vals.length / 2];
        long ops = 0;
        for (int v : vals) ops += Math.abs(v - median) / x;
        return (int) ops;
    }
}

function minOperations(grid, x) {
    const vals = [];
    for (const row of grid) {
        for (const v of row) vals.push(v);
    }
    const rem = (vals[0] % x + x) % x;
    for (const v of vals) {
        if ((v % x + x) % x !== rem) return -1;
    }
    vals.sort((a, b) => a - b);
    const median = vals[Math.floor(vals.length / 2)];
    let ops = 0;
    for (const v of vals) ops += Math.floor(Math.abs(v - median) / x);
    return ops;
}
